import{_ as t,o as e,c as o,ae as r,j as l}from"./chunks/framework.RRduUuAx.js";const d=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-操作系统-前趋图与资源图","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-操作系统-前趋图与资源图"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/前趋图与资源图.md","filePath":"综合知识/系统基础/操作系统/前趋图与资源图.md"}'),s={name:"综合知识/系统基础/操作系统/前趋图与资源图.md"};function n(i,a,c,P,p,h){return e(),o("div",null,[...a[0]||(a[0]=[r('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 前趋图概念与表示</li><li>[x] 进程资源图（阻塞节点/非阻塞节点/死锁判断）</li><li>[x] 资源图化简方法</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="前趋图" tabindex="-1">前趋图 <a class="header-anchor" href="#前趋图" aria-label="Permalink to &quot;前趋图&quot;">​</a></h3><p>用来表示哪些任务可以并行执行，哪些任务之间有顺序关系：</p><ul><li><strong>任务间的并行</strong>：无依赖关系的任务可同时执行</li><li><strong>任务间的先后顺序</strong>：前驱任务完成后，后继任务才能开始</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/7fb11113b16faf8b872591ab44db4fe4_MD5.png" alt="前趋图"></p><blockquote><p>如上图：A、B、C 可并行执行，但必须全部完成后才能执行 D。</p></blockquote><h3 id="进程资源图" tabindex="-1">进程资源图 <a class="header-anchor" href="#进程资源图" aria-label="Permalink to &quot;进程资源图&quot;">​</a></h3><p>用来表示<strong>进程和资源之间的分配和请求关系</strong>：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/779ef5c71eb95ad6caacce47a802a998_MD5.png" alt="进程资源图"></p><ul><li><strong>P 代表进程，R 代表资源</strong>，R 方框中圆球数 = 该资源的个数</li><li>R→P 箭头：资源已分配给进程</li><li>P→R 箭头：进程还需请求该资源</li></ul><p><strong>节点判断</strong>：</p><ul><li><strong>阻塞节点</strong>：进程所请求的资源已全部分配完毕，无法获取所需资源（如上图 P2）</li><li><strong>非阻塞节点</strong>：进程所请求的资源还有剩余，可以分配给该进程（如上图 P1、P3）</li><li><strong>死锁</strong>：进程资源图中<strong>所有进程都是阻塞节点</strong>时，陷入死锁</li></ul><p><strong>资源图化简方法</strong>：从非阻塞节点开始，将其所有边去掉变成孤立点，回收分配给它的资源，重复此过程直到所有节点孤立；若无法全部化简则存在死锁。</p><h3 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h3><h4 id="进程资源图判断" tabindex="-1">进程资源图判断 <a class="header-anchor" href="#进程资源图判断" aria-label="Permalink to &quot;进程资源图判断&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/Pasted%20image%2020230902164103.png" alt="进程资源图"></p><p>问题：关于图中进程状态和化简顺序，正确的是？</p><p>答案：<strong>P1、P2是阻塞节点，P3是非阻塞节点</strong>；化简顺序为 <strong>P3→P1→P2</strong>。</p><p>解析：P3 不阻塞，先孤立 P3 并回收资源 R1，此时 P1 获得 R2 变为非阻塞，孤立 P1 回收 R2，最后 P2 获得 R1 变为非阻塞。</p><h4 id="前趋图表示" tabindex="-1">前趋图表示 <a class="header-anchor" href="#前趋图表示" aria-label="Permalink to &quot;前趋图表示&quot;">​</a></h4><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20241020212603.png" alt="前趋图"></p><p>问题：图中前趋图应记为？</p>',24),l("p",{"(P1,P2),(P1,P3),(P1,P4),(P2,P3),(P2,P5),(P3,P4),(P3,P6),(P4,P7),(P5,P6),(P5,P8),(P6,P7),(P7,P8)":""},"答案：→=",-1)])])}const g=t(s,[["render",n]]);export{d as __pageData,g as default};
